```javascript
const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const T = input[0];
const N = input[1];
const cities = input.slice(2).sort((a, b) => a - b);

let minTwice = Math.min(cities[0] + cities[1], 2 * T - cities[N - 2] - cities[N - 1]);

for (let i = 1; i < N - 1; i++) {
  minTwice = Math.min(minTwice, cities[i + 1] - cities[i - 1]);
}

console.log((minTwice / 2).toFixed(2));
